def rattacher_demandes(apps, schema_editor):
    """Les analyses importées par HPRIM avant ce champ notaient leur demande
    dans le commentaire (« … demande 2026000050). ») : on la rattache."""
    import re
    Analyse = apps.get_model('laboratoire', 'AnalyseLaboratoire')
    Demande = apps.get_model('laboratoire', 'DemandeExamen')
    for analyse in Analyse.objects.filter(demande__isnull=True, commentaire__contains='demande '):
        trouve = re.search(r'demande (DEM)?(\d+)\)', analyse.commentaire)
        if trouve:
            demande = Demande.objects.filter(numero=f"DEM{trouve.group(2)}").first()
            if demande:
                analyse.demande = demande
                analyse.save(update_fields=['demande'])


